"""Edit interaction examples without dropping FM/FFM mathematics."""
from pathlib import Path
import sys
ROOT=Path(__file__).resolve().parents[2];sys.path.insert(0,str(ROOT/'tools'))
from edit_chapter import load,save,transform
paragraphs={
'Пусть вероятность покупки зависит':r'''Пусть вероятность покупки зависит от города и дня недели. В городе A выходной повышает спрос, а в B снижает. Аддитивная оценка $b+w_{city}+v_{day}$ задаёт одинаковый эффект дня для всех городов. Взаимодействие позволяет эффекту одного поля зависеть от другого.''',
'Для двух бинарных fields XOR':'''Для двух бинарных полей рассмотрим XOR: ответы (A,X)=0, (A,Y)=1, (B,X)=1, (B,Y)=0. Без взаимодействия линейная оценка с порогом не может выразить такую картину. Перекрёстная категория A×X/A×Y/B×X/B×Y даёт каждому сочетанию свой эффект, но число сочетаний растёт как произведение размеров словарей.''',
'Для additive score $s_{cd}':r'''Для аддитивной оценки $s_{cd}=b+a_c+d_d$ разность $s_{AY}-s_{AX}$ равна $d_Y-d_X$ и не зависит от города. Поэтому разность разностей $s_{AY}-s_{AX}-s_{BY}+s_{BX}$ равна нулю. Ненулевое значение требует взаимодействия в самой оценке. В логистической модели речь идёт о логите, а не о вероятностях: одна и та же прибавка к логиту может по-разному изменить вероятность при разных исходных значениях.''',
'Пусть positive означает score>0':r'''Пусть положительный ответ означает $s>0$, отрицательный — $s<0$. XOR требует $s_{AX}<0,s_{AY}>0,s_{BX}>0,s_{BY}<0$: сумма двух положительных оценок должна быть больше нуля, а двух отрицательных — меньше. Но аддитивная модель даёт $s_{AY}+s_{BX}=2b+a_A+a_B+d_X+d_Y=s_{AX}+s_{BY}$. Получено противоречие независимо от способа оптимизации.''',
'При известных categories FM':'''Для известных категорий факторизационная машина (factorization machine, FM) может представить XOR уже при d=1: зададим факторы городов A=1,B=−1 и факторов дней X=−1,Y=1. Матрица произведений равна ((−1,1),(1,−1)); порог 0 даёт нужные классы. При конечных весах sigmoid не сделает вероятности строго 0 и 1. Этот пример также не доказывает, что любая матрица взаимодействий имеет ранг 1.''',
'Если включить intercept, все city':'''Если включить перехват, индикаторы всех городов, всех дней и всех пар, часть столбцов линейно зависима. Например, индикатор города A равен сумме индикаторов AX и AY, когда у каждой строки ровно один день. Предсказания могут быть определены однозначно, а разложение на основные эффекты и взаимодействия — нет. Базовые уровни, ограничения на сумму коэффициентов или регуляризация задают конкретную параметризацию.''',
'Cross-only model с отдельным':'''Модель с отдельным коэффициентом для каждой наблюдавшейся пары может запомнить её ответ, но не имеет отдельной оценки для полностью новой пары. Основные эффекты и резервный коэффициент помогают задать поведение, однако его нужно определить явно. Отсутствующая пара в разреженной матрице, нулевой коэффициент и статистически доказанное отсутствие взаимодействия — разные вещи.''',
'Cross ключ должен быть':'''Ключ сочетания должен быть однозначным кортежем: простое склеивание `ab`+`c` и `a`+`bc` даёт одинаковую строку. Разделители, экранирование и сериализация входят в контракт. Затем сочетание кодируют через one-hot, хэш, частоту или целевую статистику с соответствующими правилами предотвращения утечки.''',
'Если city имеет 1000 values':r'''Если у города 1000 значений, а у товара 10 000, потенциально существует $10^7$ сочетаний. Наблюдаемых пар меньше, но многие редки или отсутствуют. Независимый коэффициент каждой пары плохо переносится на новые сочетания. Сглаживание и общие факторы вводят разные предположения, позволяющие делиться информацией.''',
'FM второго порядка для sparse input':'''FM второго порядка для разреженного входа задаётся формулой:''',
'Вместо независимого coefficient':'''Вместо независимого коэффициента каждой пары используется скалярное произведение двух скрытых векторов. Параметры разделяются между парами, поэтому наблюдения об одних сочетаниях влияют на оценку других. Это ограничивает множество возможных матриц взаимодействий и не гарантирует правильности для новых значений.''',
'При one-hot по fields':r'''При one-hot кодировании нескольких полей в строке активно несколько признаков. Для $v_A=(1,0)$ и $v_X=(0.2,0.5)$ эффект пары равен 0.2, а с $v_Y=(-0.3,0.1)$ — −0.3. Изменение вектора A влияет на все его взаимодействия: это даёт совместное использование информации, но связывает и ошибки разных пар.''',
'FM sum можно вычислять':'''Сумму взаимодействий FM можно вычислить без явного перебора всех пар:''',
'Это даёт cost порядка':'''При подходящей реализации стоимость пропорциональна числу активных признаков и размерности вектора. Равенство следует из раскрытия квадрата: диагональные слагаемые вычитаются, а каждое произведение пары до деления на 2 встречается дважды.''',
'Для двух fields C и D':r'''Для двух полей C и D блок взаимодействий имеет элементы $M_{cd}=e_c^\top f_d$. В матричной форме $M=EF^\top$, поэтому его ранг не больше d. Вместо $K_CK_D$ независимых коэффициентов пар обучаются $(K_C+K_D)d$ факторов. Например, 1000 городов и 10 000 товаров дают 10 миллионов отдельных коэффициентов против 176 000 факторов при d=16. Перехват, основные эффекты и состояние оптимизатора учитываются отдельно.''',
'При d=1 должна выполняться':r'''При d=1 для любого блока 2×2 выполняется $M_{11}M_{22}=M_{12}M_{21}$. Матрица ((1,2),(2,4)) этому условию удовлетворяет, а единичная матрица ((1,0),(0,1)) — нет. Увеличение d снимает часть ограничений, но увеличивает число параметров и требования к данным.''',
'Нужно аккуратно формулировать rank':r'''Для общего набора признаков утверждение о ранге требует осторожности. Полная матрица Грама $VV^\top$ имеет ранг не выше d и положительно полуопределена. Но FM использует только пары $i<j$, без взаимодействия признака с самим собой. Если удалить диагональ, ранг может вырасти: для трёх скалярных факторов, равных 1, матрица $J-I$ имеет ранг 3, хотя d=1. Поэтому утверждение о ранге блока между двумя полями нельзя автоматически переносить на всю матрицу с нулевой диагональю.''',
'Этот prior помогает':'''Это предположение полезно, когда эффекты похожих пар имеют общие причины. Если эффекты всех пар независимы и случайны, низкоранговое приближение может быть смещённым. Факторизация не создаёт отсутствующие метки; она связывает оценки предположением о структуре.''',
'Возьмём три active features':r'''Возьмём три активных признака $x=(1,2,-1)$ и векторы $v_1=(1,2)$, $v_2=(3,-1)$, $v_3=(-2,0.5)$. Значения намеренно не ограничены нулями и единицами: в FM могут входить количества, веса и числовые признаки с осмысленным масштабом.''',
'Dot products равны 1':r'''Скалярные произведения для пар 12,13,23 равны 1,−1,−6.5. С учётом множителей $x_ix_j$ их вклады составляют 2,1,13, общая сумма — 16. Без множителей x получилась бы другая функция. Линейная часть и перехват для прозрачности здесь равны нулю.''',
'Теперь вычислим $s=':r'''Теперь вычислим $s=\sum_i x_i v_i=(9,-0.5)$. Квадрат его нормы равен 81.25. Диагональная часть составляет $1^2\cdot5+2^2\cdot10+(-1)^2\cdot4.25=49.25$. Поэтому формула даёт $(81.25-49.25)/2=16$ — тот же результат без отдельного перебора пар.''',
'Если nnz активных coordinates':r'''Если активных координат m, сначала вычисляют d сумм по m признакам, затем диагональную поправку. Стоимость этого прямого прохода равна $O(md)$ и не зависит от полного размера словаря K. Состояние оптимизатора, обновление регуляризации и доступ к таблице могут стоить иначе: сложность формулы не является общим измерением времени системы.''',
'У single-valued one-hot field':'''Если поле принимает ровно одно значение и закодировано one-hot, два его разных индикатора не бывают активны одновременно: их парный член в данных равен нулю. У многозначного поля взаимодействие значений внутри поля уже возможно. Включение или исключение таких пар задаёт разную модель; предположение об одном значении нельзя молча переносить на набор интересов.'''
}
def op(t):
 for prefix,new in paragraphs.items():
  a=t.find(prefix)
  if a<0:raise ValueError('Missing paragraph: '+prefix)
  ends=[i for i in (t.find('\n\n',a),t.find('\n<!-- EDIT:',a),t.find('\n<!-- /EDIT:',a)) if i>=0]
  if not ends:raise ValueError('Missing boundary: '+prefix)
  b=min(ends);t=t[:a]+new+t[b:]
 return t
c=load();transform('01-data-features/02-features/feat-interactions.md',op,
 'Пакет 03: редактура XOR, перекрёстных признаков и FM с сохранением вывода, ранговых ограничений и примеров; приёмка ожидается.',c);save(c)
print('XOR, crosses and FM edited; source review stays open.')
